pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // caller must be distinct from the current owner to detect the missing onlyOwner guard
        vm.assume(caller != c.owner());
        // newOwner must be non-zero because transferOwnership enforces it
        vm.assume(newOwner != address(0));

        vm.prank(caller);
        c.transferOwnership(newOwner);

        // After the call, the owner should have changed ONLY if caller was the original owner.
        // Since we assumed caller ≠ owner, the call must NOT have changed the owner.
        // The reference contract respects this; the buggy contract changes it regardless.
        assertTrue(c.owner() != newOwner);
    }
}

