contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());
        vm.assume(caller != newOwner);

        address initialOwner = c.owner();
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}

        address finalOwner = c.owner();
        // Reference rule: a non-owner caller cannot change the owner via transferOwnership
        assertTrue(finalOwner == initialOwner);
    }
}

