pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address zeroAddress) public {
        // 1. Admissible domain: any address that is zero
        vm.assume(zeroAddress == address(0));

        // 2. No adversarial helper needed; the bug is internal logic.
        // Need to initialize to make the owner non-zero and pass onlyOwner.
        c.initialize();
        address originalOwner = c.owner();
        vm.prank(originalOwner);

        // 3. Assertion: transferOwnership to zero address must revert
        bool success = true;
        try c.transferOwnership(zeroAddress) {
            success = false;
        } catch {
            success = true;
        }
        assertTrue(success, "transferOwnership to zero should revert");
    }
}

