pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. Call c.initialize() to set up the ownable contract
        c.initialize();

        // 2. The property: calling transferOwnership must NOT result in owner being zero address.
        //    Transfer ownership to the fuzzed address.
        //    If the call reverts, the property holds vacuously (owner stays non-zero).
        //    The bug removes the zero-address check, making transferOwnership(address(0)) succeed
        //    and setting owner to zero, which the reference rejects.
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // If the call succeeded, owner MUST NOT be address(0).
        // For the reference, either it reverts (success=false, assertTrue(true) passes)
        // or newOwner != address(0) and owner becomes non-zero.
        // For the bug, newOwner = address(0) will succeed and owner will be address(0),
        // violating the assertion.
        if (success) {
            assertTrue(c.owner() != address(0));
        } else {
            // call reverted; property holds vacuously
            assertTrue(true);
        }
    }
}

