pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OWNER = address(0x1111);

    function setUp() public {
        c = new C();
        // Initialize the contract and set a known initial owner
        c.initialize();
        // transferOwnership from zero-address (initial owner) to INITIAL_OWNER
        vm.prank(address(0));
        c.transferOwnership(INITIAL_OWNER);
    }

    function testFuzz_property(address caller, address newOwner) public {
        // Admissible domain: caller and newOwner are not the initial owner to avoid trivial no-change scenarios.
        // We also avoid fuzzing with address(0) or current owner since the rule is about unauthorized changes.
        vm.assume(caller != INITIAL_OWNER);
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != c.owner());

        // Record the owner before the call
        address oldOwner = c.owner();

        // Non-owner caller attempts to change ownership
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // If the call succeeds
        } catch {
            // If it reverts
        }

        // The property: if caller is not the current owner, the owner should remain unchanged.
        // Because the buggy version has no onlyOwner check, a non-owner caller can change the owner.
        // We assert that oldOwner == currentOwner when caller is not oldOwner.
        // Note: the condition is that caller is not oldOwner (which we ensured via vm.assume).
        assertTrue(c.owner() == oldOwner, "Non-owner caller changed the owner");
    }
}

